  AttributeTypeKind havingEnumFirstTypeParameter(boolean isEnum) {
    if (isEnum) {
      switch (this) {
      case SET:
        return ENUM_SET;
      case MAP:
        return ENUM_MAP;
      default:
      }
    }
    return this;
