      List<ValueType> sorted = new ArrayList<>(implementations);
      sortTypesMostSpecificFirst(sorted);
      this.implementations = ImmutableList.copyOf(sorted);
    }

    public String folderMethod() {
      return "fold" + type.name();
    }
  }

  public static final class Case {
    public final ValueType implementation;
    public final List<FoldAttribute> attributes;

    Case(ValueType implementation, List<FoldAttribute> attributes) {
      this.implementation = implementation;
      this.attributes = attributes;
